 double lo=b.lower[5],hi=b.values[5];need(!feasible(lo)&&feasible(hi),"actual one-coordinate boundary bracket");while(std::nextafter(lo,hi)<hi){const double mid=lo+(hi-lo)*.5;if(mid==lo||mid==hi)break;if(feasible(mid))hi=mid;else lo=mid;}b.values[5]=hi;M::V x;std::copy_n(b.values.data(),12,x.data());ceres::SubsetManifold original(12,{11});M face(rig,range,b,&original,endpoint,x.data());bool rejected_interior=false;try{auto interior=x;interior[5]+=.001;M invalid(rig,range,b,&original,endpoint,interior.data());}catch(...){rejected_interior=true;}need(rejected_interior,"strict interior cannot become an active face");const int k=face.TangentSize();std::vector<double>d(k,0.),y(12),pj(12*k),mj(k*12);need(face.Plus(x.data(),d.data(),y.data()),"Plus zero");need(std::memcmp(x.data(),y.data(),12*8)==0,"Plus zero bit exact");need(face.PlusJacobian(x.data(),pj.data())&&face.MinusJacobian(x.data(),mj.data()),"face Jacobians");Eigen::Map<Eigen::Matrix<double,Eigen::Dynamic,Eigen::Dynamic,Eigen::RowMajor>>P(pj.data(),12,k),Q(mj.data(),k,12);need((Q*P-Eigen::MatrixXd::Identity(k,k)).cwiseAbs().maxCoeff()<1e-12,"MinusJac times PlusJac");double fd_error=0;
 for(int c=0;c<k;++c){const double h=1e-6;std::vector<double>left(12),right(12);d[c]=h;need(face.Plus(x.data(),d.data(),right.data()),"positive local face");d[c]=-h;need(face.Plus(x.data(),d.data(),left.data()),"negative local face");d[c]=0;for(int a=0;a<12;++a){const double fd=(right[a]-left[a])/(2*h);fd_error=std::max(fd_error,std::abs(fd-P(a,c))/std::max(1.,std::abs(P(a,c))));}}
 need(fd_error<2e-6,"actual implicit derivative finite difference");auto delta=j.at("actual_first_proposal_delta").get<M::V>();Eigen::VectorXd td=Q*Eigen::Map<Eigen::VectorXd>(delta.data(),12);Eigen::VectorXd small=td*1e-6;need(face.Plus(x.data(),small.data(),y.data()),"actual first proposal small tangent");std::vector<double>back(k);need(face.Minus(y.data(),x.data(),back.data()),"actual first proposal Minus");auto off_surface=y;off_surface[5]+=.001;std::vector<double>bad_minus(k);need(!face.Minus(off_surface.data(),x.data(),bad_minus.data()),"feasible off-face dependent change cannot be ignored");double roundtrip=(Eigen::Map<Eigen::VectorXd>(back.data(),k)-small).cwiseAbs().maxCoeff();need(roundtrip<1e-10,"actual Plus Minus roundtrip");
 M::V target;std::copy_n(y.data(),12,target.data());Eigen::VectorXd gradient=-td*1e8;std::vector<double>scratch(k),projected(12);const auto probe=ceres::internal::LocalGradientNormProbe(x.data(),12,gradient.data(),k,scratch.data(),projected.data(),[&](const double*a,const double*d,double*c){return face.Plus(a,d,c);},[&](const double*d,double*ambient){Eigen::Map<Eigen::VectorXd>(ambient,12)=P*Eigen::Map<const Eigen::VectorXd>(d,k);return true;});need(probe.valid&&probe.max_norm>0&&probe.rejected_probes>0,"large actual direction norm must backtrack and remain nonzero");
 eventio::Json row={{"loaded_Ceres_DLL",module.u8string()},{"loaded_Ceres_SHA256",loaded_sha},{"test_scope","actual_three_rig_parameters_and_saved_delta; synthetic_coupled_residuals; no_full_input_no_full_Solve"},{"rig",id},{"boundary_value",x[5]},{"saved_face_g",face.level()},{"tangent",k},{"finite_difference_relative_error",fd_error},{"actual_proposal_roundtrip",roundtrip},{"norm_probe_rejected",probe.rejected_probes},{"norm_probe_scale",probe.scale},{"norm_probe_max",probe.max_norm},{"norm_probe_conservative",probe.conservative}};
